using Test, GravitationalWaveforms, Printf

# SEOBNRv5HM (aligned spin, six modes) against pyseobnr 0.3.7. Reference data in test/data, generated by
# scripts/pyseobnr_hm_reference.py (`--pa`: pyseobnr's post-adiabatic inspiral, the variant this package ports)
# and the dumps described in the data files' headers.

const _HMG = GravitationalWaveforms

function _hm_unwrap(p)
    q = copy(p)
    for i in 2:length(q)
        q[i] -= 2pi * round((q[i] - q[i-1]) / (2pi))
    end
    return q
end
_hm_lin(x, y, xq) = (i = clamp(searchsortedlast(x, xq), 1, length(x) - 1); y[i] + (y[i+1] - y[i]) * (xq - x[i]) / (x[i+1] - x[i]))

@testset "SEOBNRv5 radiation-reaction force vs pyseobnr (all l <= 8 modes)" begin
    nu = X1 = X2 = c1 = c2 = 0.0
    worst = 0.0
    for l in eachline(joinpath(@__DIR__, "data", "pyseobnr037_rr_force.txt"))
        startswith(l, "#") && continue
        w = split(l)
        if w[1] == "CFG"
            q, c1, c2 = parse.(Float64, w[2:4])
            X1, X2 = q / (1 + q), 1 / (1 + q)
            nu = X1 * X2
        else
            r, pr, pphi, Hn, om, omc, Frp, Fphip = parse.(Float64, w[2:end])
            delta, chiS, chiA = X1 - X2, 0.5 * (c1 + c2), 0.5 * (c1 - c2)
            atest = (1 - 2nu) * chiS + delta * chiA
            absN = (_HMG._seobv5_multipole_prefix_abs(nu, X1, X2, lm...) for lm in ((3, 3), (2, 1), (4, 4), (3, 2), (5, 5), (4, 3)))
            Heff = ((nu * Hn)^2 - 1) / (2nu) + 1
            Fr, Fphi = _HMG._seobv5_rr_force(pr, pphi, om, omc, Heff, Hn, nu,
                _HMG._seobv5_flux_coeffs(nu, delta, chiS, chiA, atest, absN...))
            worst = max(worst, abs(Fphi / Fphip - 1), abs(Fr / Frp - 1))
        end
    end
    @test worst < 1e-13
end

@testset "SEOBNRv5HM inspiral modes vs pyseobnr compute_hlms on the same dynamics rows" begin
    b = nothing; pref = nothing; c21 = c43 = 0.0; row = nothing
    worst_amp = worst_phase = 0.0
    for l in eachline(joinpath(@__DIR__, "data", "pyseobnr037_hm_rowmodes.txt"))
        startswith(l, "#") && continue
        w = split(l)
        if w[1] == "CFG"
            q, c1, c2 = parse.(Float64, w[2:4])
            c21, c43 = parse(Float64, w[6]), parse(Float64, w[8])
            eta = q / (1 + q)^2
            b = _HMG._imr_base(SEOBNRv5IMRAlignedSpinF2(), 60.0 * eta^0.6, eta, c1, c2, 10.0, _HMG.GMsun_over_c3)
            pref = ntuple(k -> _HMG._seobv5hm_prefix(b.X1, b.X2, _HMG._SEOBV5HM_L[k], _HMG._SEOBV5HM_M[k]), 6)
        elseif w[1] == "ROW"
            row = parse.(Float64, w[2:end])
        else
            v = parse.(Float64, w[2:end])
            r, phi, pr, pphi, Hn, om, omc = row
            Heff = ((b.nu * Hn)^2 - 1) / (2b.nu) + 1
            for k in 1:6
                hp = complex(v[2k-1], v[2k]) * cis(_HMG._SEOBV5HM_M[k] * phi)
                ho = _HMG._seobv5hm_reduced_mode(k, om, omc, Hn, Heff, pphi, b, pref[k], c21, c43)
                worst_amp = max(worst_amp, abs(abs(ho) / abs(hp) - 1))
                worst_phase = max(worst_phase, abs(angle(ho / hp)))
            end
        end
    end
    @test worst_amp < 1e-12
    @test worst_phase < 1e-9        # the arg-Gamma Stirling series (~1e-11)
end

@testset "SEOBNRv5HM time-domain modes vs pyseobnr 0.3.7 (post-adiabatic inspiral)" begin
    # Peak-aligned |h_lm| and the relative phases varphi_lm - (m/2) varphi_22 (independent of the small orbital
    # dephasing); both models start at orbital frequency 0.02 with orbital phase 0. Tolerances ~1.5-2x the
    # measured errors . Ringdowns of the mixed modes (3,2), (4,3) amplify attachment differences
    # (spheroidal decomposition near a cancellation), hence their looser bounds.
    M = 60.0
    for (q, c1, c2) in ((1.25, 0.0, 0.0), (1.0, -0.6, -0.6), (4.0, 0.3, 0.0), (3.0, 0.5, -0.4), (2.0, -0.8, 0.5),
                        (8.0, 0.8, 0.2), (1.5, 0.9, 0.9), (6.0, -0.5, -0.7), (1.1, 0.3, -0.3))
        tg = "q$(@sprintf("%.2f", q))_chi$(c1)_$(c2)"
        fn = joinpath(@__DIR__, "data", "pyseobnr037_hm_$(tg)_pa.csv")
        dur = parse(Float64, split(readline(fn), "= ")[end])
        ref = [parse.(Float64, split(l, ',')) for l in eachline(fn) if !startswith(l, "#")]
        eta = q / (1 + q)^2
        t, modes, info = seobnrv5hm_td_modes(M * eta^0.6, eta, c1, c2; f_min = 0.02 / (pi * M * _HMG.GMsun_over_c3), dt = 0.1)
        @test info.success
        a22 = abs.(modes[1])
        ip = argmax(a22)
        dpk = 0.5 * (a22[ip-1] - a22[ip+1]) / (a22[ip-1] - 2a22[ip] + a22[ip+1])
        tt = t .- (t[ip] + 0.1 * dpk)
        @test isapprox(-tt[1], dur; atol = 0.5)
        vps = map(modes) do h
            vp = -_hm_unwrap(angle.(h))
            vp .+ (-angle(h[1]) - vp[1])
        end
        # (2,2) phase drift over the last 1500 M before the peak (high-spin case: open, ~0.06 rad)
        off = _hm_lin(tt, vps[1], ref[1][1]) - ref[1][3]
        e22 = maximum(abs(_hm_lin(tt, vps[1], r[1]) - off - r[3]) for r in ref if r[1] <= 0)
        @test e22 < (c1 == 0.9 ? 0.08 : 0.035)
        for k in 1:6
            m = _HMG._SEOBV5HM_M[k]
            mixed = k == 4 || k == 6
            if q == 1.0 && c1 == c2 && isodd(m)
                @test maximum(abs, modes[k]) < 1e-12       # vanishes for equal masses and spins
                continue
            end
            amp = abs.(modes[k])
            @test maximum(abs(_hm_lin(tt, amp, r[1]) / r[2k] - 1) for r in ref if r[1] <= 0) < 0.008
            @test maximum(abs(_hm_lin(tt, amp, r[1]) / r[2k] - 1) for r in ref if r[1] > 0) < (mixed ? 0.05 : 0.015)
            rel(r) = (_hm_lin(tt, vps[k], r[1]) - m / 2 * _hm_lin(tt, vps[1], r[1])) - (r[2k+1] - m / 2 * r[3])
            e0 = rel(ref[1])
            @test abs(e0) < 0.01                     # mode phase conventions (prefixes, tail, delta_lm, signs)
            @test maximum(abs(rel(r) - e0) for r in ref if r[1] <= 0) < 0.015
            @test maximum(abs(rel(r) - e0) for r in ref if r[1] > 0) < (mixed ? 0.07 : 0.03)
        end
    end
end

@testset "SEOBNRv5HM frequency-domain tables" begin
    # (1) each mode's table vs a direct Fourier sum of the time-domain mode (aLIGO design PSD, Ajith 2011 fit):
    # noise-weighted mismatch (max over time and phase shifts). The SPA region misses the merger's broadband
    # leakage into weak modes (oscillating few-% ratio in (4,3) at q ~ 1), which keeps mismatches ~1e-6..2e-5.
    psd(f) = (x = f / 215.0; x^-4.14 - 5x^-2 + 111.0 * (1 - x^2 + 0.5x^4) / (1 + 0.5x^2))
    q, c1, c2 = 3.0, 0.5, -0.4
    M = 60.0; eta = q / (1 + q)^2; mc = M * eta^0.6
    fmin = 0.012 / (pi * M * _HMG.GMsun_over_c3)
    c = _HMG._seobv5hm_coeffs(mc, eta, c1, c2; f_min = fmin)
    @test c.success
    t, modes, _ = seobnrv5hm_td_modes(mc, eta, c1, c2; f_min = fmin, dt = 0.25)
    Ms = c.M_sec
    for k in 1:6
        z = [_HMG._seobv5hm_fdsign(k) * conj(modes[k][n]) * _HMG._eobimr_turn_on((t[n] - t[1]) / 2000.0) for n in eachindex(t)]
        f = collect(range(max(3 * c.fmin[k], 20.0), 0.8 * c.fmax[k], length = 400))
        num = [Ms * 0.25 * sum(z[n] * cis(-2pi * fi * Ms * t[n]) for n in eachindex(t)) for fi in f]
        tab = [_HMG._seobv5hm_fd_eval(c, k, fi) for fi in f]
        w = 1.0 ./ psd.(f)
        best = maximum(abs(sum(conj.(num) .* tab .* cis.(2pi .* f .* dt) .* w)) for dt in range(-1e-3, 1e-3, length = 201))
        @test 1 - best / sqrt(sum(abs2.(num) .* w) * sum(abs2.(tab) .* w)) < 5e-5
    end
    # (2) the (2,2) table agrees with the (2,2)-only SEOBNRv5IMRAlignedSpinF2 table (amp e^{-i psi}, face-on factor
    # folded into amp; constant phase pi)
    o = _HMG._eobimr_coeffs(SEOBNRv5IMRAlignedSpinF2(), mc, eta, c1, c2; f_min = 15.0)
    c15 = _HMG._seobv5hm_coeffs(mc, eta, c1, c2; f_min = 15.0)
    for f in (30.0, 60.0, 100.0, 150.0, 200.0)
        a, psi = _HMG._eobimr_eval(o, f)
        r = _HMG._seobv5hm_fd_eval(c15, 1, f) / (a * cis(-psi))
        @test isapprox(abs(r), 2 / sqrt(5 / (4pi)); rtol = 2e-3)
        @test abs(angle(-r)) < 2e-3
    end
    # (3) public API: h_lm per mode (LAL h_{l,-m}), hphc = the mode sum
    m1, m2 = M * q / (1 + q), M / (1 + q)
    h33 = h_lm(SEOBNRv5HM(), 3, 3, [40.0, 80.0], m1, m2, c1, c2, 0.5; f_min = 15.0)
    @test all(isfinite, h33) && all(!iszero, h33)
    @test_throws ArgumentError h_lm(SEOBNRv5HM(), 5, 5, 40.0, m1, m2, c1, c2, 0.5)
    hp, hc = hphc(SEOBNRv5HM(), 80.0, m1, m2, c1, c2, 0.5, 1.0, 0.3; f_min = 15.0)
    hp2 = hc2 = zero(ComplexF64)
    for (l, m) in ((2, 2), (2, 1), (3, 3), (3, 2), (4, 4), (4, 3))
        hp2, hc2 = _HMG._xhm_add_mode!(hp2, hc2, l, m, h_lm(SEOBNRv5HM(), l, m, 80.0, m1, m2, c1, c2, 0.5; f_min = 15.0), 1.0, pi / 2 - 0.3)
    end
    @test hp ≈ hp2 && hc ≈ hc2
end
